const customerSteps={Accepted:'Your order was accepted by the store.',Preparing:'Your order is being prepared.','Ready for pickup':'Your order is ready for pickup.','Out for delivery':'Your order is out for delivery.',Completed:'Your order is complete.',Rejected:'Your order could not be fulfilled. Open My orders for details.'};
const accountWithAlerts=showCircleAccount;showCircleAccount=function(){accountWithAlerts();if(!window.WKCloud?.user||$('#modal').dataset.view!=='account')return;const button=document.createElement('button');button.id='customeralerts';button.innerHTML='♧ Order notifications <span>Enable →</span>';button.onclick=async()=>{button.disabled=true;try{await window.WKCloud.enableCustomerAlerts();button.textContent='Order notifications enabled ✓';notify('We’ll notify you as your order progresses.')}catch(e){notify(e.message)}finally{button.disabled=false}};$('.profile-menu').insertBefore(button,$('#profileshare'))};$('#signinbutton').onclick=showCircleAccount;
let previousCustomerOrders=new Map();const progressReceiver=window.WK.receiveOrders;window.WK.receiveOrders=function(list){progressReceiver(list);for(const order of list){const before=previousCustomerOrders.get(order.id);if(before&&before!==order.status&&customerSteps[order.status])notify(customerSteps[order.status])}previousCustomerOrders=new Map(list.map(o=>[o.id,o.status]))};
const notificationAuthChanged=window.WK.authChanged;window.WK.authChanged=function(){notificationAuthChanged();const url=new URL(location.href);if(window.WKCloud?.user&&url.searchParams.get('orders')==='1'){url.searchParams.delete('orders');history.replaceState(null,'',url.pathname+url.search+url.hash);showCustomerOrders()}};
